36	/**
37	 * Idempotent variant of {@code POST /api/owners}. Selected only when an
38	 * {@code Idempotency-Key} header is present (a more specific mapping than the
39	 * plain create), so the ordinary create path is untouched. A repeated key
40	 * returns the originally created owner with 200 instead of creating a duplicate.
41	 */
42	@RestController
43	@CrossOrigin(exposedHeaders = "errors, content-type")
44	@RequestMapping("/api")
45	public class OwnerIdempotentCreateControllerV1 {
46	
47	    private final OwnerRestControllerV1 delegate;
48	
49	    private final Map<String, OwnerDto> createdByKey = new ConcurrentHashMap<>();
50	
51	    public OwnerIdempotentCreateControllerV1(OwnerRestControllerV1 delegate) {
52	        this.delegate = delegate;
53	    }
54	
55	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
56	    @PostMapping(value = "/owners", headers = "Idempotency-Key",
57	        consumes = "application/json", produces = "application/json")
58	    public ResponseEntity<OwnerDto> addOwner(@RequestHeader("Idempotency-Key") String key,
59	                                             @Valid @RequestBody OwnerFieldsDto ownerFieldsDto) {
60	        OwnerDto existing = createdByKey.get(key);
61	        if (existing != null) {
62	            return new ResponseEntity<>(existing, HttpStatus.OK);
63	        }
64	        ResponseEntity<OwnerDto> created = delegate.addOwner(ownerFieldsDto);
65	        createdByKey.put(key, created.getBody());
66	        return created;
67	    }
68	}
