50	    @Mapping(target = "id", ignore = true)
51	    @Mapping(target = "pets", ignore = true)
52	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
53	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
54	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
55	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
56	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
57	    Owner toOwner(OwnerFieldsDto ownerDto);
58	
59	    /**
60	     * Compose the stored/returned address, preferring the structured fields: when a non-blank
61	     * {@code addressLine1} is supplied it is the normalized line 1 with the normalized
62	     * {@code addressLine2} appended after a single space (when present); otherwise fall back to
63	     * the normalized flat {@code address} for backward compatibility.
64	     */
65	    default String composeAddress(OwnerFieldsDto ownerDto) {
66	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
67	        if (line1 == null || line1.isBlank()) {
68	            return normalizeAddress(ownerDto.getAddress());
69	        }
70	        String line2 = normalizeAddress(ownerDto.getAddressLine2());
71	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
72	    }
73	
74	    /**
75	     * Canonicalise the address on create: trim, collapse whitespace runs, upper-case, and expand
76	     * the common street-type abbreviations. The normalized value is what gets stored, returned, and
77	     * compared by the household rules.
78	     */
79	    @Named("normalizeAddress")
80	    default String normalizeAddress(String address) {
81	        if (address == null) {
82	            return null;
83	        }
84	        return address.trim().replaceAll("\\s+", " ").toUpperCase()
85	            .replaceAll("\\bST\\b", "STREET")
86	            .replaceAll("\\bRD\\b", "ROAD")
87	            .replaceAll("\\bAVE\\b", "AVENUE");
88	    }
89	
90	    /** Store the telephone in E.164 form (see {@link E164Telephone#toE164}). */
91	    @Named("normalizeTelephone")
92	    default String normalizeTelephone(String telephone) {
93	        return E164Telephone.toE164(telephone);
94	    }
95	
96	    /** Lower-case the email so it is stored and returned in canonical form. */
97	    @Named("normalizeEmail")
98	    default String normalizeEmail(String email) {
99	        return email == null ? null : email.toLowerCase();
100	    }
