107	        OwnerPageDto ownerPageDto = new OwnerPageDto();
108	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
109	        ownerPageDto.setPage(ownerPage.getNumber());
110	        ownerPageDto.setSize(ownerPage.getSize());
111	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
112	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
113	        return ownerPageDto;
