2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	import org.springframework.http.HttpStatus;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.web.bind.annotation.ResponseStatus;
10	
11	/**
12	 * Business rule: an owner's effective registration date must fall on a business day. The effective
13	 * date is the one supplied on the request, or the server's current date when none was supplied; a
14	 * Saturday or Sunday rolls forward to the following Monday. Kept as a small, self-contained unit so
15	 * the rule can be applied from the create flow before any value derived from the registration date
16	 * (membership number, per-day create limit) is computed.
17	 */
18	public final class OwnerRegistrationDatePolicy {
19	
20	    private OwnerRegistrationDatePolicy() {
21	    }
22	
23	    /** Set the owner's registrationDate to its effective business-day value. */
24	    public static void assignBusinessDayRegistrationDate(Owner owner) {
25	        LocalDate supplied = owner.getRegistrationDate();
26	        rejectFutureDate(supplied);
27	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
28	        owner.setRegistrationDate(rollToBusinessDay(effective));
29	    }
30	
31	    /** Reject a supplied registration date that is later than the server's current date. */
32	    private static void rejectFutureDate(LocalDate supplied) {
33	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
34	            throw new FutureRegistrationDateException();
35	        }
36	    }
37	
38	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
39	        LocalDate.of(2026, 1, 1), LocalDate.of(2026, 1, 26), LocalDate.of(2026, 4, 25),
40	        LocalDate.of(2026, 12, 25), LocalDate.of(2026, 12, 28));
41	
42	    private static LocalDate rollToBusinessDay(LocalDate date) {
43	        while (!isBusinessDay(date)) {
44	            date = date.plusDays(1);
45	        }
46	        return date;
47	    }
48	
49	    private static boolean isBusinessDay(LocalDate date) {
50	        DayOfWeek day = date.getDayOfWeek();
51	        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !PUBLIC_HOLIDAYS.contains(date);
52	    }
53	
54	    /** Thrown when a supplied registration date is later than the server's current date. */
55	    @ResponseStatus(HttpStatus.BAD_REQUEST)
56	    public static class FutureRegistrationDateException extends RuntimeException {
57	    }
58	}
