1	package org.springframework.samples.petclinic.service;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.http.HttpStatus;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.web.bind.annotation.ResponseStatus;
8	
9	/**
10	 * Business rule: no more than {@value #DAILY_LIMIT} owners may be created on a single day
11	 * (by registrationDate). Kept as a small, self-contained unit so the rule can be enforced from
12	 * the create flow without adding complexity to the controller or service.
13	 */
14	public final class OwnerDailyLimitPolicy {
15	
16	    private static final int DAILY_LIMIT = 100;
17	
18	    private OwnerDailyLimitPolicy() {
19	    }
20	
21	    /**
22	     * Reject the owner being created if {@value #DAILY_LIMIT} or more owners already share today's
23	     * registration date.
24	     *
25	     * @param clinicService source of the existing owners
26	     * @param owner the owner being created, whose (business-day) registration date is the target day
27	     * @throws DailyLimitReachedException if today's create limit has already been reached
28	     */
29	    public static void rejectWhenDailyLimitReached(ClinicService clinicService, Owner owner) {
30	        LocalDate day = owner.getRegistrationDate();
31	        int count = 0;
32	        for (Owner existing : clinicService.findAllOwners()) {
33	            if (day.equals(existing.getRegistrationDate())) {
34	                count++;
35	            }
36	        }
37	        if (count >= DAILY_LIMIT) {
38	            throw new DailyLimitReachedException();
39	        }
40	    }
41	
42	    /** Thrown when {@value #DAILY_LIMIT} or more owners already share today's registration date. */
43	    @ResponseStatus(HttpStatus.TOO_MANY_REQUESTS)
44	    public static class DailyLimitReachedException extends RuntimeException {
45	    }
46	}
