3	import org.springframework.http.HttpStatus;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.web.bind.annotation.ResponseStatus;
6	
7	/**
8	 * Business rule: an owner cannot be created in a city that already contains {@value #CITY_CAPACITY}
9	 * or more owners. Kept as a small, self-contained unit so the rule can be enforced from the create
10	 * flow without adding complexity to the controller or service.
11	 */
12	public final class OwnerCityCapacityPolicy {
13	
14	    private static final int CITY_CAPACITY = 50;
15	
16	    private OwnerCityCapacityPolicy() {
17	    }
18	
19	    /**
20	     * Reject the given owner if its city already holds {@value #CITY_CAPACITY} or more owners.
21	     *
22	     * @param clinicService source of the existing owners
23	     * @param owner         the owner being created
24	     * @throws CityAtCapacityException if the owner's city is already at capacity
25	     */
26	    public static void rejectWhenCityAtCapacity(ClinicService clinicService, Owner owner) {
27	        String city = owner.getCity();
28	        if (city == null) {
29	            return;
30	        }
31	        int count = 0;
32	        for (Owner existing : clinicService.findAllOwners()) {
33	            if (city.equals(existing.getCity())) {
34	                count++;
35	            }
36	        }
37	        if (count >= CITY_CAPACITY) {
38	            throw new CityAtCapacityException();
39	        }
40	    }
41	
42	    /** Thrown when an owner's city already contains {@value #CITY_CAPACITY} or more owners. */
43	    @ResponseStatus(HttpStatus.CONFLICT)
44	    public static class CityAtCapacityException extends RuntimeException {
45	    }
46	}
