1	package org.springframework.samples.petclinic.service;
2	
3	import java.util.Set;
4	
5	import org.springframework.http.HttpStatus;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.web.bind.annotation.ResponseStatus;
8	
9	/**
10	 * Business rule: an owner's email must not use a disposable-email provider. The domain (the part
11	 * after the last {@code @}, compared case-insensitively) is rejected when it appears on a fixed
12	 * blocklist (mailinator.com, tempmail.com, guerrillamail.com). Email is optional: an owner created
13	 * without one, or with no {@code @}, passes unchanged. Kept as a small, self-contained unit so the
14	 * rule can be enforced from the create flow without adding complexity to the controller or service.
15	 */
16	public final class OwnerDisposableEmailPolicy {
17	
18	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
19	        "mailinator.com", "tempmail.com", "guerrillamail.com");
20	
21	    private OwnerDisposableEmailPolicy() {
22	    }
23	
24	    /**
25	     * Reject the owner when its email domain is on the disposable-domain blocklist.
26	     *
27	     * @param owner the owner being created
28	     * @throws DisposableEmailException if the email domain is blocklisted
29	     */
30	    public static void rejectDisposableDomain(Owner owner) {
31	        String email = owner.getEmail();
32	        if (email == null) {
33	            return;
34	        }
35	        int at = email.lastIndexOf('@');
36	        if (at < 0) {
37	            return;
38	        }
39	        String domain = email.substring(at + 1).toLowerCase();
40	        if (DISPOSABLE_DOMAINS.contains(domain)) {
41	            throw new DisposableEmailException();
42	        }
43	    }
44	
45	    /** Thrown when an owner's email domain is on the disposable-domain blocklist. */
46	    @ResponseStatus(HttpStatus.BAD_REQUEST)
47	    public static class DisposableEmailException extends RuntimeException {
48	    }
49	}
