3	import org.springframework.http.HttpStatus;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.web.bind.annotation.ResponseStatus;
6	
7	/**
8	 * Business rule: every owner is identified by a single derived {@code identityKey}: the SHA-256
9	 * hex of {@code normalizedTelephone|lowerEmail|soundex(lastName)}. On creation an owner is
10	 * rejected only when its identityKey exactly matches an existing (non-deleted) owner's. Because the
11	 * telephone is part of the key, two owners with the same last name and postcode but DIFFERENT
12	 * telephones have different identityKeys and are both created — the second is flagged a soft match
13	 * by {@link OwnerPossibleDuplicatePolicy} rather than rejected. Kept as a small, self-contained unit
14	 * so the rule can be enforced from the create flow without adding complexity to the controller or
15	 * service.
16	 *
17	 * <p>Field canonicalisation is delegated to {@link OwnerFieldNormalizer} and the surname's phonetic
18	 * code to {@link Soundex}, keeping this class focused on the identity key itself.
19	 */
20	public final class OwnerIdentityPolicy {
21	
22	    private OwnerIdentityPolicy() {
23	    }
24	
25	    /**
26	     * Reject the owner when its identityKey matches any existing non-deleted owner's; otherwise flag
27	     * it as a possible duplicate when it soft-matches one (see {@link OwnerPossibleDuplicatePolicy}).
28	     *
29	     * @param clinicService source of the existing owners
30	     * @param owner         the owner being created
31	     * @throws DuplicateIdentityException if the identityKey is already in use
32	     */
33	    public static void rejectDuplicateIdentity(ClinicService clinicService, Owner owner) {
34	        String key = identityKey(owner);
35	        for (Owner existing : clinicService.findAllOwners()) {
36	            if (!existing.isDeleted() && !existing.getId().equals(owner.getId())
37	                && key.equals(identityKey(existing))) {
38	                throw new DuplicateIdentityException();
39	            }
40	        }
41	        OwnerPossibleDuplicatePolicy.assignPossibleDuplicate(clinicService, owner);
42	    }
43	
44	    /** The owner's derived identity key: SHA-256 hex of {@code telephone|email|soundex(lastName)}. */
45	    public static String identityKey(Owner owner) {
46	        return Sha256Hex.lower("V2|" + OwnerFieldNormalizer.telephone(owner.getTelephone()) + "|"
47	            + OwnerFieldNormalizer.email(owner.getEmail()) + "|"
48	            + Soundex.of(owner.getLastName()), 32);
49	    }
50	
51	    /** Thrown when another owner already has the same identityKey. */
52	    @ResponseStatus(HttpStatus.CONFLICT)
53	    public static class DuplicateIdentityException extends RuntimeException {
54	    }
55	}
