2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Business rule: an owner that is not a hard duplicate but whose {@code soundex(lastName)} and
7	 * postcode match an existing (non-deleted) owner's — while its identityKey differs — is still
8	 * created and flagged as a possible duplicate. On creation the owner records
9	 * {@code possibleDuplicateOf} (the matching owner's id), from which {@code possibleDuplicate} is
10	 * derived; when nothing matches it stays absent. Kept as a small, self-contained unit so the rule
11	 * can be applied from the create flow without adding complexity to the controller or service.
12	 */
13	public final class OwnerPossibleDuplicatePolicy {
14	
15	    private OwnerPossibleDuplicatePolicy() {
16	    }
17	
18	    /**
19	     * Record {@code possibleDuplicateOf} for a newly created owner when a non-deleted owner shares
20	     * its {@code soundex(lastName)} and postcode but has a different identityKey.
21	     *
22	     * @param clinicService source of the existing owners
23	     * @param owner         the owner being created
24	     */
25	    public static void assignPossibleDuplicate(ClinicService clinicService, Owner owner) {
26	        String postcode = OwnerFieldNormalizer.orEmpty(owner.getPostcode());
27	        if (postcode.isEmpty()) {
28	            return;
29	        }
30	        String soundex = Soundex.of(owner.getLastName());
31	        String key = OwnerIdentityPolicy.identityKey(owner);
32	        for (Owner existing : clinicService.findAllOwners()) {
33	            if (!existing.isDeleted() && !existing.getId().equals(owner.getId())
34	                && soundex.equals(Soundex.of(existing.getLastName()))
35	                && postcode.equals(OwnerFieldNormalizer.orEmpty(existing.getPostcode()))
36	                && !key.equals(OwnerIdentityPolicy.identityKey(existing))) {
37	                owner.setPossibleDuplicateOf(existing.getId());
38	                return;
39	            }
40	        }
41	    }
42	}
